    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate n, r, t so the coefficient |C| is substantial but not astronomically large.
# We'll use the known identity: prod_{i=1}^n (1 - q^i y) = sum_{t=0}^n (-1)^t q^{t(t+1)/2} [n choose t]_q y^t,
# with q = r^2 and y = x^2. So |C| = q^{t(t+1)/2} * [n choose t]_q.

def qbinom(n, k, q):
    # Gaussian binomial coefficient [n choose k]_q as exact integer via product formula.
    num = 1
    den = 1
    for j in range(1, k+1):
        num *= pow(q, n - k + j) - 1
        den *= pow(q, j) - 1
    # It is known this ratio is an integer; we safeguard anyway.
    if num % den != 0:
        return None
    return num // den

def compute_abs_coeff(n, r, t):
    q = r * r
    qb = qbinom(n, t, q)
    if qb is None:
        return None
    return pow(q, t * (t + 1) // 2) * qb

# Try bounded ranges to keep answers manageable and nontrivial.
for _ in range(100):
    n = rng.randint(4, 6)
    r = rng.choice([2, 2, 3])  # bias toward smaller q to keep magnitudes reasonable
    t_max = min(3, n)  # cap t to keep numbers from exploding
    t = rng.randint(2, t_max)
    val = compute_abs_coeff(n, r, t)
    if val is None:
        continue
    # Difficulty filter: ensure it's not tiny and not too huge
    if val >= 1000 and val <= 10**12:
        return {'n': n, 'r': r, 't': t}
# Fallback deterministic instance
return {'n': 4, 'r': 2, 't': 2}

